module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    logic       state;   // 0: State A, 1: State B
    logic [1:0] cnt;     // Cycle counter within the 3-cycle window (0, 1, 2)
    logic [1:0] ones;    // Count of 1s in the current 3-cycle window

    always_ff @(posedge clk) begin
        if (reset) begin
            state <= 1'b0;
            cnt   <= 2'd0;
            ones  <= 2'd0;
            z     <= 1'b0;
        end else begin
            if (state == 1'b0) begin
                // State A: wait for s = 1
                z <= 1'b0;
                if (s) begin
                    state <= 1'b1;
                    cnt   <= 2'd0;
                    ones  <= {1'b0, w}; // Cycle 1 of the first window
                end
            end else begin
                // State B: process w in 3-cycle windows continuously
                if (cnt == 2'd0) begin
                    cnt   <= 2'd1;
                    ones  <= ones + {1'b0, w}; // Cycle 2 of window
                    z     <= 1'b0;
                end else if (cnt == 2'd1) begin
                    cnt   <= 2'd2;
                    ones  <= ones + {1'b0, w}; // Cycle 3 of window
                    // Evaluate z for the following clock cycle
                    z     <= ((ones + {1'b0, w}) == 2);
                end else begin // cnt == 2
                    cnt   <= 2'd0;
                    ones  <= {1'b0, w}; // Cycle 1 of the next window
                    z     <= 1'b0;
                end
            end
        end
    end

endmodule

